bool seleccionar(int*& actual, std::array<int, 3>& datos, int indice) {
    if (indice < 0 || indice > 2) {
        return false;
    }
    // Falta guardar la seleccion; de momento solo compara la anterior.
    return actual == &datos.at(static_cast<std::size_t>(indice));
}

void intercambiar(int*& primero, int*& segundo) {
    if (primero == segundo) {
        return;
    }
    // Falta intercambiar las selecciones distintas.
}

void vaciar(int*& actual) {
    actual = nullptr;
}

std::string escribir(int* destino, int valor) {
    if (destino == nullptr) {
        return "Sin objeto";
    }
    if (valor < 0 || valor > 9) {
        return "Rechazo";
    }
    *destino = valor;
    return "Cambio";
}

int main() {
    std::array<int, 3> datos{2, 5, 8};
    int* actual = nullptr;
    int* guardado = nullptr;
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    for (int orden = 0; orden < cantidad; ++orden) {
        int operacion = 0;
        int argumento = 0;
        if (!(std::cin >> operacion >> argumento)) {
            return 1;
        }
        std::string estado = "Orden";
        if (operacion == 1) {
            estado = seleccionar(actual, datos, argumento) ? "Seleccion" : "Rechazo";
        } else if (operacion == 2) {
            guardado = actual;
            estado = "Guardado";
        } else if (operacion == 3) {
            intercambiar(actual, guardado);
            estado = "Intercambio";
        } else if (operacion == 4) {
            vaciar(actual);
            estado = "Vacio";
        } else if (operacion == 5) {
            estado = escribir(actual, argumento);
        } else if (operacion == 6) {
            estado = escribir(guardado, argumento);
        }
        std::cout << "Estado:" << estado << ";Actual:";
        if (actual == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *actual;
        }
        std::cout << ";Guardado:";
        if (guardado == nullptr) {
            std::cout << 'X';
        } else {
            std::cout << *guardado;
        }
        std::cout << ";Datos:" << datos[0] << ',' << datos[1] << ',' << datos[2] << '\n';
    }
    return 0;
}

